result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/heroScene.js", "content": "import * as THREE from 'three';

/**
 * Builds the landing page hero scene:
 * - a pedestal the product sits on
 * - a product placeholder mesh named "product" at the origin
 * - three point lights for the rotating showcase
 */
export function buildHero() {
  const scene = new THREE.Scene();

  // Pedestal: a short cylinder under the product.
  const pedestal = new THREE.Mesh(
    new THREE.CylinderGeometry(1.5, 1.8, 0.4, 32),
    new THREE.MeshStandardMaterial({ color: 0x222831, roughness: 0.6 })
  );
  pedestal.name = 'pedestal';
  pedestal.position.y = -0.2;
  scene.add(pedestal);

  // Product placeholder at the origin.
  const product = new THREE.Mesh(
    new THREE.BoxGeometry(1, 1, 1),
    new THREE.MeshStandardMaterial({ color: 0x76b5c5, roughness: 0.3, metalness: 0.2 })
  );
  product.name = 'product';
  product.position.set(0, 0, 0);
  scene.add(product);

  // Three point lights arranged around the showcase.
  const lightColors = [0xffffff, 0xffd9a0, 0xa0c8ff];
  const radius = 6;
  for (let i = 0; i < 3; i++) {
    const angle = (i / 3) * Math.PI * 2;
    const light = new THREE.PointLight(lightColors[i], 1.2);
    light.name = `hero-light-${i}`;
    light.position.set(
      Math.cos(angle) * radius,
      3,
      Math.sin(angle) * radius
    );
    scene.add(light);
  }

  return scene;
}
"})
