result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/cameraRig.js", "content": "import * as THREE from 'three';

// Reusable scratch objects so rigPose allocates nothing per frame.
const _tmpObject = new THREE.Object3D();
const _target = new THREE.Vector3(0, 0, 0);

/**
 * Builds a camera rig from an array of keyframe positions.
 * The keyframes become a closed Catmull-Rom spline the camera travels along.
 */
export function makeOrbitRig(keyframes) {
  if (!Array.isArray(keyframes) || keyframes.length < 2) {
    throw new Error('makeOrbitRig requires at least two keyframes');
  }
  const curve = new THREE.CatmullRomCurve3(
    keyframes.map((p) => p.clone()),
    true // closed loop
  );
  return { curve };
}

/**
 * Returns {position, quaternion} for the rig at parameter t in [0, 1).
 * Values outside [0, 1) wrap around the loop. Orientation uses a temp
 * Object3D that lookAts the origin, matching the showcase's focal point.
 */
export function rigPose(rig, t) {
  const wrapped = ((t % 1) + 1) % 1;

  const position = rig.curve.getPointAt(wrapped);

  _tmpObject.position.copy(position);
  _tmpObject.up.set(0, 1, 0);
  _tmpObject.lookAt(_target);

  const quaternion = new THREE.Quaternion().copy(_tmpObject.quaternion);

  return { position, quaternion };
}
"})
