result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/rig.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildHero } from '../src/heroScene.js';
import { makeOrbitRig, rigPose } from '../src/cameraRig.js';

const KEYFRAMES = [
  new THREE.Vector3(5, 2, 0),
  new THREE.Vector3(0, 3, 5),
  new THREE.Vector3(-5, 2, 0),
  new THREE.Vector3(0, 4, -5),
];

describe('buildHero', () => {
  it('contains exactly three point lights', () => {
    const scene = buildHero();
    const lights = [];
    scene.traverse((obj) => {
      if (obj.isPointLight) lights.push(obj);
    });
    expect(lights.length).toBe(3);
  });

  it('has a mesh named "product" at the origin', () => {
    const scene = buildHero();
    const product = scene.getObjectByName('product');
    expect(product).toBeDefined();
    expect(product.position.x).toBe(0);
    expect(product.position.y).toBe(0);
    expect(product.position.z).toBe(0);
  });
});

describe('rigPose', () => {
  const rig = makeOrbitRig(KEYFRAMES);

  it('at t=0 sits on the first keyframe', () => {
    const { position } = rigPose(rig, 0);
    const first = KEYFRAMES[0];
    expect(position.distanceTo(first)).toBeLessThanOrEqual(1e-9);
  });

  it('loops: positions at t=0.25 and t=1.25 are equal', () => {
    const a = rigPose(rig, 0.25).position;
    const b = rigPose(rig, 1.25).position;
    expect(a.distanceTo(b)).toBeLessThan(1e-9);
  });

  it('camera forward (-Z) points toward the origin for sampled t values', () => {
    const forward = new THREE.Vector3(0, 0, -1);
    const samples = 20;

    for (let i = 0; i < samples; i++) {
      const t = i / samples;
      const { position, quaternion } = rigPose(rig, t);

      const lookDir = forward.clone().applyQuaternion(quaternion);

      // Must be a unit vector.
      expect(Math.abs(lookDir.length() - 1)).toBeLessThan(1e-3);

      // Must point from the camera position toward the origin.
      const expected = position.clone().negate().normalize();
      expect(lookDir.angleTo(expected)).toBeLessThan(1e-3);
    }
  });
});
"})
